                        x,y=a+da,b+db
                        if 0<=x<h and 0<=y<w and g[x][y]==col and (x,y) not in seen:
                            seen.add((x,y)); st.append((x,y))
                out.append((col,cells))
    return out

def norm(cells):
    m=min(a for a,b in cells); n=min(b for a,b in cells)
    return tuple(sorted((a-m,b-n) for a,b in cells))

def mindist(c1,c2):
    return min(abs(a-x)+abs(b-y) for a,b in c1 for x,y in c2)

def transform(grid):
    g=[row[:] for row in grid]
    bg=collections.Counter(x for row in g for x in row).most_common(1)[0][0]
    cs=comps(g,bg)
    cnt=collections.Counter(col for col,c in cs)
    singles=[col for col,n in cnt.items() if n==1 and col!=bg]
    sh=collections.defaultdict(list)
    for col,c in cs: sh[norm(c)].append((col,c))
    best=None
    for s,v in sh.items():
        if len(v)>=2 and (best is None or len(s)>len(best[0])): best=(s,v)
    s,v=best
    if len(singles)==1:
        anchor_col=singles[0]
    else:
        # anchor = singleton whose object is closest to a pair member
        def score(col):
            a=[c for k,c in cs if k==col][0]
            return min(mindist(a,m[1]) for m in v)
        anchor_col=min(singles,key=score)
